SELECT set_config('test.uid','33333333-3333-3333-3333-333333333333',false);
DO $$ DECLARE mid uuid; f uuid; result jsonb; BEGIN
 mid:=chairman_add_member('11111111-1111-1111-1111-111111111111','{"name":"Disposable member","fee_category_id":"22222222-2222-2222-2222-222222222222"}');
 IF (SELECT sum(amount) FROM club_member_fee_payments WHERE club_member_id=mid)<>1300 OR (SELECT count(*) FROM club_member_fee_payments WHERE club_member_id=mid)<>2 OR EXISTS(SELECT 1 FROM club_member_fee_payments WHERE club_member_id=mid AND paid) THEN RAISE EXCEPTION 'Configured unpaid joining fees failed'; END IF;
 PERFORM chairman_ensure_joining_fee(mid);
 IF (SELECT count(*) FROM club_member_fee_payments WHERE club_member_id=mid)<>2 THEN RAISE EXCEPTION 'Duplicate joining fee'; END IF;
 UPDATE club_members SET is_pending_approval=true WHERE id=mid;
 PERFORM review_membership_application(mid,true);
 IF (SELECT is_pending_approval FROM club_members WHERE id=mid) THEN RAISE EXCEPTION 'Approval failed'; END IF;
 BEGIN PERFORM chairman_add_member('11111111-1111-1111-1111-111111111111','{"name":"Bad role","role":"admin"}'); RAISE EXCEPTION 'Role bypass'; EXCEPTION WHEN raise_exception THEN IF SQLERRM='Role bypass' THEN RAISE; END IF; END;
 INSERT INTO club_members(id,club_id,name,is_pending_approval) VALUES('77777777-7777-7777-7777-777777777777','11111111-1111-1111-1111-111111111111','Pending',true);
 UPDATE club_members SET fee_category_id='22222222-2222-2222-2222-222222222222' WHERE id='77777777-7777-7777-7777-777777777777';
 PERFORM review_membership_application('77777777-7777-7777-7777-777777777777',true);
 IF (SELECT sum(amount) FROM club_member_fee_payments WHERE club_member_id='77777777-7777-7777-7777-777777777777')<>1300 THEN RAISE EXCEPTION 'Unbilled approval fee missing'; END IF;
 INSERT INTO club_champs_registrations(id,champ_id,club_member_id,status) VALUES('88888888-8888-8888-8888-888888888888','44444444-4444-4444-4444-444444444444',mid,'invited');
 BEGIN PERFORM accept_tournament_invite('88888888-8888-8888-8888-888888888888',true,ARRAY[1]); RAISE EXCEPTION 'Other member bypass'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 result:=accept_tournament_invite('55555555-5555-5555-5555-555555555555',true,ARRAY[1]);
 f:=(result->>'fee_payment_id')::uuid;
 IF f IS NULL OR (SELECT amount FROM club_member_fee_payments WHERE id=f)<>150 OR (SELECT paid FROM club_member_fee_payments WHERE id=f) THEN RAISE EXCEPTION 'Self entry fee failed'; END IF;
 PERFORM accept_tournament_invite('55555555-5555-5555-5555-555555555555',true,ARRAY[1]);
 IF (SELECT count(*) FROM club_member_fee_payments WHERE fee_type='tournament_entry')<>1 THEN RAISE EXCEPTION 'Duplicate entry fee'; END IF;
 PERFORM charge_tournament_entry_to_account('55555555-5555-5555-5555-555555555555');
 IF (SELECT fee_settled_via FROM club_champs_registrations WHERE id='55555555-5555-5555-5555-555555555555')<>'account' THEN RAISE EXCEPTION 'Account entry failed'; END IF;
 BEGIN UPDATE club_member_fee_payments SET paid=true WHERE id=f; RAISE EXCEPTION 'Paid bypass'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN INSERT INTO club_journal_entries(club_id,debit) VALUES('11111111-1111-1111-1111-111111111111',10); RAISE EXCEPTION 'Journal bypass'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN UPDATE club_champs_registrations SET status='waived' WHERE id='55555555-5555-5555-5555-555555555555'; RAISE EXCEPTION 'Waiver bypass'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN PERFORM chairman_add_member('66666666-6666-6666-6666-666666666666','{"name":"Wrong club"}'); RAISE EXCEPTION 'Scope bypass'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 INSERT INTO tournaments VALUES('99999999-9999-9999-9999-999999999999','11111111-1111-1111-1111-111111111111','Free test',0,false,'2026-10-29','on_entry');
 INSERT INTO club_champs_registrations(id,champ_id,club_member_id,status) VALUES('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','99999999-9999-9999-9999-999999999999','33333333-3333-3333-3333-333333333333','invited');
 PERFORM accept_tournament_invite('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',true,ARRAY[1]);
 IF (SELECT status FROM club_champs_registrations WHERE id='aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa')<>'paid' THEN RAISE EXCEPTION 'Free entry blocked'; END IF;
 IF EXISTS(SELECT 1 FROM chairman_action_context) THEN RAISE EXCEPTION 'Context leaked'; END IF;
 IF EXISTS(SELECT 1 FROM information_schema.role_table_grants WHERE table_name='chairman_action_context' AND grantee IN ('authenticated','anon')) THEN RAISE EXCEPTION 'Context client access'; END IF;
